// Confidence-scored match. Same normalisation as ops.normalise_company_name.
// 1.0 exact normalised name; 0.9 domain stem equals normalised title, or a previous company name matches;
// 0.85 prefix (>= 6 chars, lengths within 60%); 0.7 weak prefix or token overlap incl. the brand word (review only).
// If the best hit is not active and an active candidate scores >= 0.7, the active one wins.
// CRO-hinted (.ie) rows cap at 0.7: a UK registry hit is never trusted for an Irish domain.
const a = $('Prepare search name').item.json;
const norm = s => String(s || '').toLowerCase().replace(/\b(ltd|limited|llp|plc|uk|group|holdings)\b/g, '').replace(/[^a-z0-9]/g, '');
const toks = s => String(s || '').toLowerCase().replace(/\b(ltd|limited|llp|plc|uk|group|holdings|the|and|co|company)\b/g, ' ').split(/[^a-z0-9]+/).filter(t => t.length > 2);
const items = Array.isArray($json.items) ? $json.items : [];
const target = norm(a.search_name || a.name);
const targetFull = norm(a.name);
const stem = a.domain ? norm(String(a.domain).split('.')[0]) : '';
const A = toks(a.search_name || a.name); const brand = A[0] || '';
const score = i => {
  const t = norm(i.title);
  if (!t) return [0, 'none'];
  if (t === target || t === targetFull) return [1.0, 'exact'];
  if (stem && stem.length >= 5 && t === stem) return [0.9, 'domain'];
  if (Array.isArray(i.previous_company_names) && i.previous_company_names.some(p => norm(p.name) === target)) return [0.9, 'previous_name'];
  if (target.length >= 6 && (t.startsWith(target) || target.startsWith(t))) {
    const r = Math.min(t.length, target.length) / Math.max(t.length, target.length);
    return r >= 0.6 ? [0.85, 'prefix'] : [0.7, 'weak_prefix'];
  }
  const B = new Set(toks(i.title));
  const inter = A.filter(x => B.has(x)).length;
  const j = (A.length && B.size) ? inter / (A.length + B.size - inter) : 0;
  if (j >= 0.6 && inter >= 2 && brand && B.has(brand)) return [0.7, 'tokens'];
  return [0, 'none'];
};
const scored = items.map(i => { const [c, b] = score(i); return { i, c, b }; }).filter(x => x.c > 0);
scored.sort((x, y) => y.c - x.c);
let best = scored[0] || null;
if (best && best.i.company_status !== 'active') {
  const alt = scored.find(x => x.i.company_status === 'active' && x.c >= 0.7);
  if (alt) best = alt;
}
let conf = best ? best.c : 0;
if (best && a.registry_hint === 'CRO') conf = Math.min(conf, 0.7);
return { json: {
  account_id: a.account_id, name: a.name, domain: a.domain, registry_hint: a.registry_hint,
  company_number: best ? best.i.company_number : null,
  registered_name: best ? best.i.title : null,
  status: best ? best.i.company_status : null,
  incorporated_on: best ? (best.i.date_of_creation || null) : null,
  match_confidence: conf, matched_by: best ? best.b : 'none',
  candidates: items.slice(0, 3).map(i => ({ n: i.company_number, t: i.title, s: i.company_status }))
} };

// Combine match + profile + PSC into one intel_save_registry payload.
const m = $('Pick CH match').item.json;
let p = {}; try { p = $('Companies House profile').item.json || {}; } catch (e) {}
const pscItems = Array.isArray($json.items) ? $json.items : [];
const UK = new Set(['united kingdom','england','scotland','wales','northern ireland','great britain','uk','england and wales']);
const country = x => String(x || '').toLowerCase().trim();
let foreign_psc = false;
for (const s of pscItems) {
  if (s.ceased_on) continue;
  const corp = /corporate|legal-person/.test(String(s.kind || ''));
  const c = country((s.identification && (s.identification.country_registered || s.identification.place_registered)) || (s.address && s.address.country));
  if (corp && c && !UK.has(c) && !/united kingdom|england|scotland|wales/.test(c)) foreign_psc = true;
}
const acc = (p.accounts && p.accounts.last_accounts && p.accounts.last_accounts.type) ? p.accounts.last_accounts.type : null;
return { json: {
  p_account_id: m.account_id,
  p_registry: 'CH',
  p_company_number: m.company_number,
  p_registered_name: p.company_name || m.registered_name,
  p_status: p.company_status || m.status,
  p_incorporated_on: p.date_of_creation || m.incorporated_on || null,
  p_sic_codes: Array.isArray(p.sic_codes) ? p.sic_codes : null,
  p_accounts_type: acc,
  p_foreign_psc: foreign_psc,
  p_officer_countries: null,
  p_match_confidence: m.match_confidence,
  p_matched_by: m.matched_by,
  p_raw: { company_type: p.type || null, registered_office: p.registered_office_address || null, psc_count: pscItems.length, candidates: m.candidates }
} };

// Search Companies House on the brand, not the strapline. "MacKenzie King - Accountancy and Finance Recruitment" → "MacKenzie King".
const raw = String($json.name || '').trim();
let s = raw.split(/\s+[-|:–]\s+/)[0].trim();
if (s.length < 4) s = raw;
s = s.replace(/[.,]+$/, '').trim();
return { json: { ...$json, search_name: s } };
